-- Worcester, the second city. Its council records come from PrimeGov (the city's
-- agenda system) and its website, not Legistar, so councilors have no numeric
-- person id: they are keyed by name ("worcester-khrystian-king").
alter table public.local_officials drop constraint local_officials_id_check;
alter table public.local_officials add constraint local_officials_id_check
  check (id ~ '^[a-z]+-(p[0-9]+|[a-z0-9-]+)$');
alter table public.local_officials alter column person_id drop not null;
comment on column public.local_officials.id is
  '{city}-p{Legistar PersonId} (Boston, e.g. boston-p324) or {city}-{name slug} (Worcester)';

-- Council committees and their members, for cities that publish them (Worcester;
-- Boston's Legistar lists no committee members, so its committees come from hearings).
create table public.local_committees (
  id text primary key,
  city text not null,
  slug text not null,
  name text not null,
  description text,
  url text,
  updated_at timestamptz not null default now(),
  unique (city, slug)
);

create table public.local_committee_members (
  committee_id text not null references public.local_committees (id) on delete cascade,
  seq smallint not null,
  official_id text,
  name text not null,
  role text,
  primary key (committee_id, seq)
);
create index local_committee_members_official_idx on public.local_committee_members (official_id);

-- A city's capital budget, one row per project line, as adopted or proposed for a
-- fiscal year (Worcester publishes it once a year as a PDF; see load-worcester-budget).
create table public.local_capital_items (
  city text not null,
  fiscal_year smallint not null,
  stage text not null check (stage in ('proposed', 'adopted')),
  seq smallint not null,
  department text not null,
  category text,
  title text not null,
  description text,
  borrowing numeric not null default 0,
  cash numeric not null default 0,
  new_authorization numeric not null default 0,
  prior_authorization numeric not null default 0,
  grants numeric not null default 0,
  primary key (city, fiscal_year, stage, seq)
);

create table public.local_capital_documents (
  city text not null,
  fiscal_year smallint not null,
  stage text not null check (stage in ('proposed', 'adopted')),
  title text not null,
  source_url text not null,
  -- The plan's five-year totals by area and department, as printed: [{area, department, years: [n,…]}].
  plan_years smallint[],
  plan jsonb,
  loaded_at timestamptz not null default now(),
  primary key (city, fiscal_year, stage)
);

alter table public.local_committees enable row level security;
alter table public.local_committee_members enable row level security;
alter table public.local_capital_items enable row level security;
alter table public.local_capital_documents enable row level security;
create policy "Public read" on public.local_committees for select to anon, authenticated using (true);
create policy "Public read" on public.local_committee_members for select to anon, authenticated using (true);
create policy "Public read" on public.local_capital_items for select to anon, authenticated using (true);
create policy "Public read" on public.local_capital_documents for select to anon, authenticated using (true);
revoke insert, update, delete, truncate on public.local_committees, public.local_committee_members,
  public.local_capital_items, public.local_capital_documents from anon, authenticated;

